const ResponsePayloadSchemaJSON = "{\"$defs\":{\"AccessDetail\":{\"additionalProperties\":true,\"description\":\"An authorization detail (HCP 6.1.5); under HCP's OAuth Interop Profile, an RFC 9396 authorization detail (HCP 13.3). `onwardSharing` appears only in a detail that includes `read` and all of whose categories have a default sensitivity of Low (HCP 6.1.5); not checked by the schema.\",\"properties\":{\"actions\":{\"description\":\"What the detail allows. `provenance` is an action only alongside `read` (HCP 6.1.5, 7.4.1); not checked by the schema.\",\"items\":{\"enum\":[\"read\",\"write\",\"provenance\"],\"type\":\"string\"},\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true},\"categories\":{\"description\":\"The categories the detail covers (HCP 4.5).\",\"items\":{\"$ref\":\"#/$defs/Category\"},\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true},\"narrowedTo\":{\"additionalProperties\":true,\"description\":\"An implementation-defined narrowing below category grain, which only narrows (HCP 6.1.5.1). To a Context Client, entries it names are named by `ref`, never by `id` (HCP 5.2.6).\",\"type\":\"object\"},\"onwardSharing\":{\"$ref\":\"#/$defs/OnwardSharing\",\"description\":\"The onward sharing the person elected for the detail (HCP 3.12, 6.1.5).\"},\"purposes\":{\"description\":\"The purposes the person approved for these categories; never empty (HCP 6.1.5.2).\",\"items\":{\"$ref\":\"#/$defs/Purpose\"},\"minItems\":1,\"type\":\"array\"},\"type\":{\"const\":\"https://hcp.example/spec/authorization/context-access\",\"description\":\"The HCP authorization detail type (HCP 6.1.5).\",\"type\":\"string\"}},\"required\":[\"type\",\"actions\",\"categories\",\"purposes\"],\"type\":\"object\"},\"AuthorizingPrincipal\":{\"additionalProperties\":true,\"description\":\"The Authorizing Principal (HCP 3.4). In Core it is the Context Subject and carries the same pseudonym as `subject`; under the Delegated Authorization Profile it is the delegate (HCP 17.4).\",\"properties\":{\"delegation\":{\"description\":\"The delegation under which a delegate authorized the grant; present only then (HCP 6.1.5, 17.4).\",\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"},\"id\":{\"description\":\"Its identifier.\",\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"}},\"required\":[\"id\"],\"type\":\"object\"},\"Category\":{\"description\":\"An HCP context category (HCP 4.5), the primary unit of access control: either a slug from HCP's category registry, such as `general_preferences` or `health_context`, or a custom category written as an absolute URI under a domain its definer controls. A custom category is not portable between providers without bilateral agreement (HCP 4.5).\",\"maxLength\":2048,\"minLength\":1,\"pattern\":\"^([a-z][a-z0-9_]*|[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+)$\",\"type\":\"string\"},\"Grant\":{\"additionalProperties\":true,\"description\":\"A grant (HCP 6.1.5). `expiresAt` is an instant for a `temporary` grant and null for a `persistent` one (HCP 6.1.4, 6.1.5). That rule is stated here and not as a schema conditional: the registry's Rust generator does not support `if`/`then`/`else`, so it is not checked by the schema. An HCP Provider never discloses a grant issued to one HCP Client to any other (HCP 6.1.5).\",\"properties\":{\"access\":{\"description\":\"What the grant authorizes: one or more authorization details (HCP 6.1.5).\",\"items\":{\"$ref\":\"#/$defs/AccessDetail\"},\"minItems\":1,\"type\":\"array\"},\"authorizingPrincipal\":{\"$ref\":\"#/$defs/AuthorizingPrincipal\",\"description\":\"Who authorized the grant (HCP 3.4, 6.1.5).\"},\"client\":{\"$ref\":\"#/$defs/GrantClient\",\"description\":\"The HCP Client the grant was issued to (HCP 6.1.5).\"},\"expiresAt\":{\"description\":\"For a temporary grant, its absolute expiry, never null; for a persistent grant, null (HCP 6.1.4, 6.1.5).\",\"format\":\"date-time\",\"type\":[\"string\",\"null\"]},\"grantId\":{\"$ref\":\"#/$defs/Urn\",\"description\":\"Stable for the life of the grant; the `grantId` recorded in audit events (HCP 6.1.5, 8.2).\"},\"grantType\":{\"description\":\"Temporary or persistent (HCP 6.1.4). HCP's own values, carried verbatim.\",\"enum\":[\"temporary\",\"persistent\"],\"type\":\"string\"},\"issuedAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When the grant was issued.\"},\"requestingParty\":{\"$ref\":\"#/$defs/RequestingParty\",\"description\":\"The party on whose behalf the client requested access, where there is one (HCP 3.2.7, 3.4).\"},\"scopes\":{\"description\":\"Scope strings derived from `access`, in the form `hcp:{category}:{action}` (HCP 6.1.1), for display. They never grant anything `access` does not (HCP 6.1.5).\",\"items\":{\"maxLength\":2048,\"pattern\":\"^hcp:[^:]+(:[^:]+)*:(read|write)$\",\"type\":\"string\"},\"type\":\"array\"},\"status\":{\"description\":\"`expired` on lapse of `expiresAt`, `revoked` on revocation (HCP 6.1.5, 6.2.1). HCP's own values, carried verbatim.\",\"enum\":[\"active\",\"revoked\",\"expired\"],\"type\":\"string\"},\"subject\":{\"$ref\":\"#/$defs/GrantParty\",\"description\":\"The Context Subject, by a pseudonym specific to the client (HCP 3.4).\"}},\"required\":[\"grantId\",\"subject\",\"authorizingPrincipal\",\"client\",\"access\",\"grantType\",\"issuedAt\",\"expiresAt\",\"status\"],\"type\":\"object\"},\"GrantClient\":{\"additionalProperties\":true,\"description\":\"The client a grant was issued to (HCP 6.1.5).\",\"properties\":{\"claims\":{\"description\":\"The client conformance claims it declared at registration (HCP 18.1); absent where it declared none.\",\"items\":{\"$ref\":\"#/$defs/Uri\"},\"type\":\"array\",\"uniqueItems\":true},\"id\":{\"description\":\"Its client identifier.\",\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"},\"legalRetention\":{\"$ref\":\"#/$defs/LegalRetention\",\"description\":\"Present only where the client declared a legal obligation to keep what it receives (HCP 6.2.5).\"},\"name\":{\"description\":\"A name the person can recognize (HCP 6.1.5).\",\"maxLength\":1024,\"minLength\":1,\"type\":\"string\"},\"operator\":{\"$ref\":\"#/$defs/Named\",\"description\":\"The Client Operator (HCP 3.2.8).\"}},\"required\":[\"id\",\"name\",\"operator\"],\"type\":\"object\"},\"GrantParty\":{\"additionalProperties\":true,\"description\":\"An actor a grant binds, named by identifier (HCP 3.4).\",\"properties\":{\"id\":{\"description\":\"Its identifier; for the Context Subject, a pseudonym specific to the client (HCP 3.4). The minLength is a framework bound, not an HCP requirement.\",\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"}},\"required\":[\"id\"],\"type\":\"object\"},\"Instant\":{\"description\":\"An RFC 3339 instant.\",\"format\":\"date-time\",\"type\":\"string\"},\"LegalRetention\":{\"additionalProperties\":true,\"description\":\"A record the client declared at registration that the law requires it to keep of what it receives (HCP 6.2.5).\",\"properties\":{\"obligation\":{\"description\":\"The law or rule that requires it.\",\"maxLength\":4096,\"type\":\"string\"},\"period\":{\"description\":\"How long it is kept.\",\"maxLength\":1024,\"type\":\"string\"},\"record\":{\"description\":\"The record kept.\",\"maxLength\":4096,\"type\":\"string\"}},\"required\":[\"record\",\"obligation\",\"period\"],\"type\":\"object\"},\"Named\":{\"additionalProperties\":true,\"description\":\"An organization, by identifier and a name a person can recognize.\",\"properties\":{\"id\":{\"description\":\"Its identifier.\",\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"},\"name\":{\"description\":\"Its name. The minLength is a framework bound, not an HCP requirement.\",\"maxLength\":1024,\"minLength\":1,\"type\":\"string\"}},\"required\":[\"id\",\"name\"],\"type\":\"object\"},\"OnwardSharing\":{\"additionalProperties\":true,\"description\":\"Present only where the Authorizing Principal elected onward sharing for the detail (HCP 3.12, 6.1.5).\",\"properties\":{\"domains\":{\"description\":\"Where present, the DNS domains of the organizations the client may share with (HCP 6.1.5).\",\"items\":{\"maxLength\":253,\"minLength\":1,\"type\":\"string\"},\"type\":\"array\",\"uniqueItems\":true},\"notTo\":{\"description\":\"Set by the provider: each DNS domain or operator a standing rule denies any of the detail's categories (HCP 6.1.5, 6.3).\",\"items\":{\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"},\"type\":\"array\",\"uniqueItems\":true}},\"type\":\"object\"},\"Purpose\":{\"additionalProperties\":true,\"description\":\"A purpose with a description the person can read (HCP 6.1.5.2).\",\"properties\":{\"code\":{\"$ref\":\"#/$defs/PurposeCode\",\"description\":\"The purpose code.\"},\"description\":{\"description\":\"The description shown to the person before approval (HCP 6.1.5.2, 6.1.6).\",\"maxLength\":4096,\"minLength\":1,\"type\":\"string\"}},\"required\":[\"code\",\"description\"],\"type\":\"object\"},\"PurposeCode\":{\"description\":\"An HCP purpose code: an absolute URI naming the purpose for which context is requested or may be used (HCP 6.1.5.2).\",\"format\":\"uri\",\"maxLength\":2048,\"minLength\":1,\"pattern\":\"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+$\",\"type\":\"string\"},\"RequestingParty\":{\"additionalProperties\":true,\"description\":\"The Requesting Party (HCP 3.2.7).\",\"properties\":{\"id\":{\"description\":\"Its identifier.\",\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"},\"name\":{\"description\":\"Its name.\",\"maxLength\":1024,\"type\":\"string\"},\"type\":{\"description\":\"A person or an organization. HCP's own values, carried verbatim.\",\"enum\":[\"person\",\"organization\"],\"type\":\"string\"}},\"required\":[\"type\",\"id\"],\"type\":\"object\"},\"Response\":{\"$anchor\":\"response\",\"additionalProperties\":false,\"description\":\"The person approved: the grant evidence, as HCP's OAuth token response carries it (HCP 13.3, 13.4), and the grant as approved, as HCP's grant object (HCP 6.1.5). Sent only after the person's affirmative act (HCP 6.1.6); while they decide the provider answers trust-task-next-step, and a decline is trust-task-error permissionDenied — never this shape.\",\"properties\":{\"accessToken\":{\"description\":\"The HCP access token for the new grant (the token response's `access_token`, HCP 13.3), opaque to the client. The client presents it unchanged as `accessToken` in hcp/entries/query and every other hcp/* task it sends under the grant. Its lifetime follows HCP 13.4 (default 1 hour, at most 24 hours). The maxLength is a framework bound, not an HCP requirement.\",\"maxLength\":8192,\"minLength\":1,\"type\":\"string\"},\"grant\":{\"$ref\":\"#/$defs/Grant\",\"description\":\"The grant as the person approved it, as HCP's grant object (HCP 6.1.5) and as hcp/grants/read-own returns it: `access` may be narrower than asked (HCP 13.3: the token response carries the authorization details granted), `status` is `active`, and `expiresAt` is null for a persistent grant. `authorizingPrincipal.delegation` is withheld, as from any Context Client reading its own grant (HCP 17.4).\"},\"tokenExpiresAt\":{\"$ref\":\"#/$defs/Instant\",\"description\":\"When `accessToken` stops being accepted (the token response's `expires_in`, HCP 13.4, as an instant), in whole seconds. Never after the grant's `expiresAt`.\"}},\"required\":[\"accessToken\",\"tokenExpiresAt\",\"grant\"],\"title\":\"HCP — Request Grant — response payload\",\"type\":\"object\"},\"Uri\":{\"description\":\"An absolute URI with no whitespace, as HCP writes every custom value at an extension point (HCP A.3).\",\"format\":\"uri\",\"maxLength\":2048,\"minLength\":1,\"pattern\":\"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+$\",\"type\":\"string\"},\"Urn\":{\"description\":\"An HCP identifier: a UUID in `urn:uuid:` form, of any UUID version (HCP 4.2), as HCP uses for entry, grant, directive and retrieval identifiers.\",\"pattern\":\"^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\",\"type\":\"string\"}},\"$ref\":\"#/$defs/Response\",\"$schema\":\"https://json-schema.org/draft/2020-12/schema\"}"

// Spec is the SPEC §7.2 policy for the request variant, taken from this
// specification's front matter. Pass it to trusttasks.ConsumeInbound — items 5b,
// 7 and 8 are per-specification and cannot be derived from the document alone,
// and item 2 needs the schema it carries.
var Spec = trusttasks.SpecPolicy{
	TypeURI:             TypeURI,
	IsBearer:            false,
	IsProofRequired:     true,
	IsRecipientRequired: true,
	IsIssuedAtRequired:  true,
	PayloadSchema:       PayloadSchemaJSON,
}

// ResponseSpec is the SPEC §7.2 policy for the success-response variant.
// IsRecipientRequired tracks the *issuer* party's requirement, because a response
// swaps the parties (§7.3 item 5).
var ResponseSpec = trusttasks.SpecPolicy{
	TypeURI:             ResponseTypeURI,
	IsBearer:            false,
	IsProofRequired:     true,
	IsRecipientRequired: true,
	IsIssuedAtRequired:  true,
	PayloadSchema:       ResponsePayloadSchemaJSON,
	MaxDocumentBytes:    1048576,
}
